import { and, count, desc, eq, gt, isNotNull, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { restorePatch } from "@/lib/soft-delete";
import { getDb, invitations, members } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvitation, toMember } from "./_mappers";
import type { CreateInvitationInput } from "@/schemas/invitation";
import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Invitation, Member, Role } from "@/types/member";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export async function insertInvitation(
  orgId: OrgId,
  input: CreateInvitationInput,
  invitedBy: UserId,
  tokenHash: string,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + input.expiresInDays * MS_PER_DAY),
  );

  const row = getDb()
    .insert(invitations)
    .values({
      id: newId(),
      orgId,
      email: input.email,
      role: input.role,
      invitedBy,
      tokenHash,
      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvitation(row);
}

/**
 * The accept flow runs before a session exists, so this is the one read in the
 * repository layer that is not scoped by `orgId` — the token hash is the
 * credential and carries the tenant with it.
 */
export async function findInvitationByTokenHash(
  tokenHash: string,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
  return row ? toInvitation(row) : null;
}

export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
      ),
    )
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

export async function markInvitationAccepted(
  orgId: OrgId,
  invitationId: InvitationId,
  at: IsoTimestamp,
): Promise<Invitation> {
  const row = getDb()
    .update(invitations)
    .set({ acceptedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

/** Consumes an invitation and creates or re-admits its membership atomically. */
export async function acceptInvitationForUser(input: {
  orgId: OrgId;
  invitationId: InvitationId;
  userId: UserId;
  role: Role;
  invitedBy: UserId;
  acceptedAt: IsoTimestamp;
}): Promise<{ member: Member; admitted: boolean }> {
  const db = getDb();

  return db.transaction((tx) => {
    const invitation = tx
      .update(invitations)
      .set({ acceptedAt: input.acceptedAt, updatedAt: input.acceptedAt })
      .where(
        and(
          orgPredicate(invitations.orgId, input.orgId),
          eq(invitations.id, input.invitationId),
          isNull(invitations.acceptedAt),
          isNull(invitations.revokedAt),
          gt(invitations.expiresAt, input.acceptedAt),
        ),
      )
      .returning()
      .get();

    if (!invitation) {
      throw new Error("That invitation is no longer available");
    }

    const existing = tx
      .select()
      .from(members)
      .where(
        and(
          orgPredicate(members.orgId, input.orgId),
          eq(members.userId, input.userId),
        ),
      )
      .get();

    if (existing && existing.archivedAt !== null) {
      const row = tx
        .update(members)
        .set({
          ...restorePatch(new Date(input.acceptedAt)),
          role: input.role,
          status: "active",
          invitedBy: input.invitedBy,
          joinedAt: input.acceptedAt,
        })
        .where(
          and(
            orgPredicate(members.orgId, input.orgId),
            eq(members.id, existing.id),
            isNotNull(members.archivedAt),
          ),
        )
        .returning()
        .get();

      if (!row) throw new Error("That membership changed while accepting the invitation");
      return { member: toMember(row), admitted: true };
    }

    if (existing) return { member: toMember(existing), admitted: false };

    const row = tx
      .insert(members)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        role: input.role,
        status: "active",
        invitedBy: input.invitedBy,
        joinedAt: input.acceptedAt,
        lastSeenAt: null,
        createdAt: input.acceptedAt,
        updatedAt: input.acceptedAt,
      })
      .returning()
      .get();

    return { member: toMember(row), admitted: true };
  });
}

export async function revokeInvitation(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(invitations)
    .set({ revokedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Invitation ${invitationId} not found`);
  return toInvitation(row);
}

/** Pending invites hold a seat, so the seat quota counts them. */
export async function countPendingInvitations(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}
