/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** A user may only hold work in an organization with a live active membership. */
export class WorkspaceMembershipConflictError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly orgId: OrgId, readonly userId: UserId) {
    super(`User ${userId} is not an active member of organization ${orgId}`);
    this.name = "WorkspaceMembershipConflictError";
  }
}

export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId | null,
): Promise<void> {
  if (userId === null) return;
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new WorkspaceMembershipConflictError(orgId, userId);
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

