/**
 * Ordinary lookups and lists only expose live rows. Historical lookups are
 * explicit and reserved for conflict handling and re-invites.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

/**
 * The (org, user) lookup behind actor resolution. Archived rows are invisible
 * here so a previously valid session stops resolving after removal.
 */
export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

